weave.init("[YOUR-TEAM]/inference-quickstart")

client = openai.OpenAI(
    base_url='https://api.inference.wandb.ai/v1',
    api_key="[REDACTED_SECRET]",  # Replace with your actual API key
    project="[YOUR-TEAM]/my-first-weave-project",  # Required for usage tracking
)

